const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};

const body = $input.first().json.body;
const entry = body.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];

const phone = message?.from;
const text = message?.text?.body;
const timestamp = message?.timestamp;

if (!phone || !text) {
  throw new Error('Build Conversation History: no se pudo extraer phone/text del payload de Meta. Payload: ' + JSON.stringify(body));
}

if (!staticData.sessions[phone]) {
  staticData.sessions[phone] = [];
}

staticData.sessions[phone].push({ role: 'user', content: text });

const MAX_HISTORY = 20;
if (staticData.sessions[phone].length > MAX_HISTORY) {
  staticData.sessions[phone] = staticData.sessions[phone].slice(-MAX_HISTORY);
}

const systemPrompt = {
  role: 'system',
  content: `Eres el asistente de ventas de Avaxon Technologies en WhatsApp. Tu único objetivo es lograr que el prospecto agende un diagnóstico gratuito de 30 minutos con el equipo de Avaxon.

SOBRE AVAXON: Automatizamos WhatsApp Business con IA. Ayudamos a negocios a atender leads 24/7, dar seguimiento automático a clientes y gestionar conversaciones sin esfuerzo manual. Nos conectamos a la API oficial de WhatsApp Business.

HORARIO DISPONIBLE PARA LLAMADAS: Lunes a viernes, de 8:00 AM a 5:00 PM (hora de México).

REGLAS OBLIGATORIAS (nunca las rompas):
- Mensajes cortos: máximo 3-4 líneas por respuesta.
- Una sola pregunta por mensaje. Nunca hagas dos preguntas al mismo tiempo.
- NUNCA pidas el número de teléfono. Ya lo tienes porque el prospecto está hablando por WhatsApp.
- Si proponen un horario fuera del rango (fin de semana, antes de 8am, después de 5pm), redirige amablemente indicando el horario disponible y pide que elijan otra opción.
- No inventes precios ni hagas compromisos específicos de precio.
- No presentes todos los servicios de golpe en el primer mensaje.

FLUJO DE CONVERSACIÓN — SIGUE ESTE ORDEN ESTRICTAMENTE:

ETAPA 1 - BIENVENIDA
Saluda de forma breve y cálida. Pregunta solamente: ¿Quieres conocer más sobre cómo funciona Avaxon, o prefieres agendar directamente tu diagnóstico gratuito?
NO expliques los planes ni servicios todavía.

ETAPA 2 - CALIFICACIÓN RÁPIDA (solo si el prospecto pide más información)
Haz UNA sola pregunta: ¿A qué se dedica tu negocio?
Con su respuesta, da UNA frase personalizada de cómo Avaxon les ayudaría en específico.
Luego invítalos a agendar el diagnóstico.

ETAPA 3 - AGENDAMIENTO
Informa el horario disponible:

- Si el prospecto ya quiere agendar desde el inicio, salta directamente a la ETAPA 3.`
};

return [
  {
    json: {
      phone,
      text,
      timestamp,
      messages: [systemPrompt, ...staticData.sessions[phone]]
    }
  }
];

const staticData = $getWorkflowStaticData('global');
const phone = $('Build Conversation History').item.json.phone;

const openaiResponse = $input.first().json;
const reply = openaiResponse.choices?.[0]?.message?.content;

if (!reply) {
  throw new Error('Extract Response: OpenAI no devolvió una respuesta válida. Respuesta cruda: ' + JSON.stringify(openaiResponse));
}

if (!staticData.sessions) staticData.sessions = {};
if (!staticData.sessions[phone]) staticData.sessions[phone] = [];
staticData.sessions[phone].push({ role: 'assistant', content: reply });

const MAX_HISTORY = 20;
if (staticData.sessions[phone].length > MAX_HISTORY) {
  staticData.sessions[phone] = staticData.sessions[phone].slice(-MAX_HISTORY);
}

return [
  {
    json: {
      phone,
      reply
    }
  }
];
